/*
 * A069763  Frobenius number of the numerical semigroup generated by
 *          consecutive cubes.
 * https://oeis.org/A069763
 *
 * Offset:    2    (a(2) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = n^3*(n+1)^3 - n^3 - (n+1)^3 = n^6 + 3*n^5 + 3*n^4 - n^3 -
 *            3*n^2 - 3*n - 1
 * Range:     u8 n <= 2, u16 n <= 5, u32 n <= 26, u64 n <= 26, u128 n <= 26,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n < 2)          /* undefined for indices below 2, but return 0 */
        return 0;

    seq_t N = (seq_t)n;

    /* Use 128‑bit integer when available in order to avoid overflow
       for the unsigned 64‑bit build on values that fit. */
#if defined(__SIZEOF_INT128__)
    unsigned __int128 x = (unsigned __int128)N;
    unsigned __int128 r =
        x*x*x*x*x*x                           /* n^6   */
      + (unsigned __int128)3*x*x*x*x*x      /* 3n^5  */
      + (unsigned __int128)3*x*x*x*x        /* 3n^4  */
      - x*x*x                               /* n^3   */
      - (unsigned __int128)3*x*x            /* 3n^2  */
      - (unsigned __int128)3*x              /* 3n    */
      - 1;
    return (seq_t)r;
#else
    /* Fallback: all operations in seq_t. Works for arbitrary‑precision
       seq_t types and for small enough n that 64‑bit multiplication does
       not overflow. */
    seq_t n2 = N * N;          /* n^2   */
    seq_t n3 = n2 * N;         /* n^3   */
    seq_t n4 = n2 * n2;        /* n^4   */
    seq_t n5 = n4 * N;         /* n^5   */
    seq_t n6 = n5 * N;         /* n^6   */

    seq_t n1 = N + 1;   /* n+1 */
    seq_t n12 = n1 * n1;            /* (n+1)^2 */
    seq_t n13 = n12 * n1;           /* (n+1)^3 */

    seq_t res = n6 + (seq_t)3 * n5 + (seq_t)3 * n4
                - n3 - (seq_t)3 * n2 - (seq_t)3 * N - 1;
    return res;
#endif
}
